export interface EditorState {
  readonly dialog: "none" | "group" | "pass";
  readonly groupDraft: string;
  readonly passDraft: string;
  readonly groups: readonly string[];
  readonly passes: readonly string[];
}

export type EditorAction =
  | { readonly type: "open"; readonly dialog: "group" | "pass" }
  | { readonly type: "edit"; readonly dialog: "group" | "pass"; readonly value: string }
  | { readonly type: "cancel" }
  | { readonly type: "save" };

export function reduceEditor(state: EditorState, action: EditorAction): EditorState {
  const detached = (): EditorState => ({
    ...state,
    groups: [...state.groups],
    passes: [...state.passes]
  });

  switch (action.type) {
    case "open": {
      const base = detached();
      if (action.dialog === "group") {
        return { ...base, dialog: "group", groupDraft: "" };
      }
      if (action.dialog === "pass") {
        return { ...base, dialog: "pass", passDraft: "" };
      }
      throw new TypeError("invalid dialog");
    }

    case "edit": {
      if (typeof action.value !== "string" || action.dialog !== state.dialog) {
        throw new TypeError("inactive dialog");
      }
      const base = detached();
      if (state.dialog === "group") return { ...base, groupDraft: action.value };
      if (state.dialog === "pass") return { ...base, passDraft: action.value };
      throw new TypeError("no open dialog");
    }

    case "cancel": {
      const base = detached();
      if (state.dialog === "group") {
        return { ...base, dialog: "none", groupDraft: "" };
      }
      if (state.dialog === "pass") {
        return { ...base, dialog: "none", passDraft: "" };
      }
      if (state.dialog === "none") return base;
      throw new TypeError("invalid dialog");
    }

    case "save": {
      if (state.dialog === "none") throw new TypeError("no open dialog");
      if (state.dialog !== "group" && state.dialog !== "pass") {
        throw new TypeError("invalid dialog");
      }

      const value = state.dialog === "group" ? state.groupDraft : state.passDraft;
      if (!value) throw new TypeError("blank draft");
      const base = detached();

      return state.dialog === "group"
        ? { ...base, dialog: "none", groupDraft: "", groups: [...base.groups, value] }
        : { ...base, dialog: "none", passDraft: "", passes: [...base.passes, value] };
    }

    default:
      throw new TypeError("unknown action");
  }
}

