import { reduceEditor } from './solution';

function eq(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message + ': ' + JSON.stringify(actual));
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw error; }
  throw new Error(message);
}
function detached(result: any, input: any, message: string): void {
  if (result.groups === input.groups || result.passes === input.passes) throw new Error(message);
}

const initial: any = { dialog: 'none', groupDraft: 'old group', passDraft: 'old pass', groups: ['Existing'], passes: ['Original'] };
const openedGroup: any = reduceEditor(initial, { type: 'open', dialog: 'group' } as any);
eq(openedGroup, { dialog: 'group', groupDraft: '', passDraft: 'old pass', groups: ['Existing'], passes: ['Original'] }, 'opening group clears only group draft');
eq(initial, { dialog: 'none', groupDraft: 'old group', passDraft: 'old pass', groups: ['Existing'], passes: ['Original'] }, 'open does not mutate input');
detached(openedGroup, initial, 'open arrays detached');

const editedGroup: any = reduceEditor(openedGroup, { type: 'edit', dialog: 'group', value: '  New Group  ' } as any);
eq(editedGroup.groupDraft, '  New Group  ', 'edit preserves whitespace');
eq(openedGroup.groupDraft, '', 'edit does not mutate input');
const savedGroup: any = reduceEditor(editedGroup, { type: 'save' } as any);
eq(savedGroup, { dialog: 'none', groupDraft: '', passDraft: 'old pass', groups: ['Existing', 'New Group'], passes: ['Original'] }, 'save trims, appends, closes, and clears');
detached(savedGroup, editedGroup, 'saved arrays detached');

const openedPass: any = reduceEditor(savedGroup, { type: 'open', dialog: 'pass' } as any);
eq(openedPass.passDraft, '', 'opening pass clears pass draft');
eq(openedPass.groupDraft, '', 'opening pass preserves group draft');
const editedPass: any = reduceEditor(openedPass, { type: 'edit', dialog: 'pass', value: '\t Evening Pass \n' } as any);
const savedPass: any = reduceEditor(editedPass, { type: 'save' } as any);
eq(savedPass.passes, ['Original', 'Evening Pass'], 'pass save appends trimmed title');
eq(savedPass.groups, ['Existing', 'New Group'], 'pass save preserves groups');
eq(savedPass.dialog, 'none', 'pass save closes dialog');
eq(savedPass.passDraft, '', 'pass save clears draft');

const cancelInput: any = { dialog: 'group', groupDraft: 'discard', passDraft: 'keep', groups: ['G'], passes: ['P'] };
const cancelled: any = reduceEditor(cancelInput, { type: 'cancel' } as any);
eq(cancelled, { dialog: 'none', groupDraft: '', passDraft: 'keep', groups: ['G'], passes: ['P'] }, 'cancel clears only current draft');
eq(cancelInput.groupDraft, 'discard', 'cancel does not mutate input');
detached(cancelled, cancelInput, 'cancel arrays detached');

const blank: any = { dialog: 'pass', groupDraft: 'g', passDraft: ' \t ', groups: ['G'], passes: ['P'] };
const blankBefore = JSON.stringify(blank);
throwsType(() => reduceEditor(blank, { type: 'save' } as any), 'blank save rejected');
eq(JSON.stringify(blank), blankBefore, 'failed blank save does not mutate');
throwsType(() => reduceEditor(initial, { type: 'save' } as any), 'save with no dialog rejected');
eq(JSON.stringify(initial), JSON.stringify({ dialog: 'none', groupDraft: 'old group', passDraft: 'old pass', groups: ['Existing'], passes: ['Original'] }), 'failed closed save does not mutate');
throwsType(() => reduceEditor(openedGroup, { type: 'edit', dialog: 'pass', value: 'wrong' } as any), 'edit for inactive dialog rejected');
throwsType(() => reduceEditor(initial, { type: 'edit', dialog: 'group', value: 'wrong' } as any), 'edit while closed rejected');
throwsType(() => reduceEditor(initial, { type: 'unknown' } as any), 'unknown action rejected');

savedPass.groups.push('mutated');
savedPass.passes.push('mutated');
eq(editedPass.groups, ['Existing', 'New Group'], 'result groups do not alias input');
eq(editedPass.passes, ['Original'], 'result passes do not alias input');

